-- Public tracking token for repair follow-up page (/suivi/:token).
-- Generated by the database (gen_random_bytes), never by the browser.
ALTER TABLE public.repairs
  ADD COLUMN tracking_token text NOT NULL DEFAULT encode(gen_random_bytes(24), 'hex');

CREATE UNIQUE INDEX repairs_tracking_token_key ON public.repairs (tracking_token);

COMMENT ON COLUMN public.repairs.tracking_token IS 'Jeton secret de suivi public ; seules les donnees en liste blanche sont exposees via la fonction serveur.';